head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getColumnType]<br/>Body Column 정보를 사용하여 특정 Body Column 의 inputType 속성값을 반환합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 inputType 속성값을 조회할 Body Column 의 인덱스를 설정할 수 있어야 합니다.",
        "columnInfo(필수) 파라미터의 Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정됩니다.",
        "반환값으로 파라미터에 해당하는 Body Column 의 inputType 속성값을 반환해야 합니다.",
        "해당 Column 이 존재하지 않으면 undefined 값을 반환합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : gridView Column 이 지원하는 모든 inputType 17종을 각 Column 으로 구성한다.
//  (inputType @option 순서: text,link,checkbox,button,image,radio,select,calendar,expression,
//   textarea,drilldown,textImage,checkcombobox,autoComplete,secret,custom,spinner)
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_grade !== 'undefined') {
        $p.data.remove("dlt_grade");
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] gridView 가 지원하는 모든 inputType 17종을 Body Column 으로 구성(인덱스 0~16, @option 순서). 각 Column 은 해당 inputType 으로 보이도록 데이터 설정(image/textImage=아이콘, textarea=여러 줄, expression=spinner x 1000 계산값, checkbox/radio=체크/선택, select/checkcombobox=라벨, secret=마스킹, calendar=날짜, spinner=숫자). 인덱스 15(custom) 는 setColumnVisible(15,false) 로 숨김(숨김 Column 도 인덱스 포함).\n[절차] (getColumnType 전체 조회) 버튼 1개 클릭.\n[확인] 모든 Column 의 inputType 이 한 번에 출력됨(0=text … 16=spinner). 숨김(15)도 custom 반환, 존재하지 않는 인덱스(99)=undefined."', '', 'label1');

    // select/radio/checkcombobox/autoComplete Column 의 itemset 용 DataList (코드/라벨)
    let strGrade = '';
    strGrade += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_grade" baseNode="list" repeatNode="map">';
    strGrade += '<w2:columnInfo>';
    strGrade += '<w2:column id="code" name="code" dataType="text"></w2:column>';
    strGrade += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strGrade += '</w2:columnInfo>';
    strGrade += '<w2:data use="true"></w2:data>';
    strGrade += '</w2:dataList>';
    $p.data.create(strGrade);
    dlt_grade.setJSON([
        { "code": "A", "label": "최우수" },
        { "code": "B", "label": "우수" },
        { "code": "C", "label": "보통" }
    ], false);

    // 실제 서빙되는 아이콘 이미지 (image / textImage 가 화면에 보이도록)
    let imgSrc = "/cm/images/contents/btn_folder.png";

    // GridView 와 바인딩할 DataList 동적 생성 (각 inputType 별 데이터 컬럼)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="ctext" name="ctext" dataType="text"></w2:column>';
    strDlt += '<w2:column id="clink" name="clink" dataType="text"></w2:column>';
    strDlt += '<w2:column id="ccheck" name="ccheck" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cbtn" name="cbtn" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cimg" name="cimg" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cradio" name="cradio" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cselect" name="cselect" dataType="text"></w2:column>';
    strDlt += '<w2:column id="ccal" name="ccal" dataType="text"></w2:column>';
    strDlt += '<w2:column id="ctextarea" name="ctextarea" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cdrill" name="cdrill" dataType="text"></w2:column>';
    strDlt += '<w2:column id="ctextimg" name="ctextimg" dataType="text"></w2:column>';
    strDlt += '<w2:column id="ccombo" name="ccombo" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cauto" name="cauto" dataType="text"></w2:column>';
    strDlt += '<w2:column id="csecret" name="csecret" dataType="text"></w2:column>';
    strDlt += '<w2:column id="ccustom" name="ccustom" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cspin" name="cspin" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "ctext": "노트북", "clink": "상세보기", "ccheck": "Y", "cbtn": "실행", "cimg": imgSrc, "cradio": "Y", "cselect": "A", "ccal": "20250115", "ctextarea": "재고확인\n2층 보관", "cdrill": "1팀", "ctextimg": "정상", "ccombo": "A B", "cauto": "A", "csecret": "1234", "ccustom": "커스텀1", "cspin": "5" },
        { "ctext": "모니터", "clink": "상세보기", "ccheck": "N", "cbtn": "실행", "cimg": imgSrc, "cradio": "N", "cselect": "B", "ccal": "20250220", "ctextarea": "신규입고\n검수 대기", "cdrill": "2팀", "ctextimg": "지연", "ccombo": "B C", "cauto": "B", "csecret": "5678", "ccustom": "커스텀2", "cspin": "10" },
        { "ctext": "키보드", "clink": "상세보기", "ccheck": "Y", "cbtn": "실행", "cimg": imgSrc, "cradio": "Y", "cselect": "C", "ccal": "20250312", "ctextarea": "할인적용\n20% 할인", "cdrill": "3팀", "ctextimg": "정상", "ccombo": "A C", "cauto": "C", "csecret": "9012", "ccustom": "커스텀3", "cspin": "15" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    let properties = {
        dataList: "data:dlt_bind",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // itemset 공통 조각 (select/checkcombobox/autoComplete 용)
    let itemset = '<w2:choices><w2:itemset nodeset="data:dlt_grade"><w2:label ref="label"></w2:label><w2:value ref="code"></w2:value></w2:itemset></w2:choices>';

    // target 생성 (지원 inputType 17종 컬럼)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:100%;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getColumnType 테스트 그리드 (지원 inputType 전체)"></w2:caption>';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="80" inputType="text" id="h0" value="text"></w2:column>';
    strTarget += '<w2:column width="80" inputType="text" id="h1" value="link"></w2:column>';
    strTarget += '<w2:column width="70" inputType="text" id="h2" value="checkbox"></w2:column>';
    strTarget += '<w2:column width="70" inputType="text" id="h3" value="button"></w2:column>';
    strTarget += '<w2:column width="60" inputType="text" id="h4" value="image"></w2:column>';
    strTarget += '<w2:column width="60" inputType="text" id="h5" value="radio"></w2:column>';
    strTarget += '<w2:column width="100" inputType="text" id="h6" value="select"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="h7" value="calendar"></w2:column>';
    strTarget += '<w2:column width="80" inputType="text" id="h8" value="expression"></w2:column>';
    strTarget += '<w2:column width="100" inputType="text" id="h9" value="textarea"></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="h10" value="drilldown"></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="h11" value="textImage"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="h12" value="checkcombobox"></w2:column>';
    strTarget += '<w2:column width="110" inputType="text" id="h13" value="autoComplete"></w2:column>';
    strTarget += '<w2:column width="70" inputType="text" id="h14" value="secret"></w2:column>';
    strTarget += '<w2:column width="80" inputType="text" id="h15" value="custom(숨김)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="h16" value="spinner"></w2:column>';
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="brow1">';
    //  (중요) body 컬럼 id 는 dataList 컬럼 id 와 동일해야 셀에 데이터가 바인딩됨
    // 0 text
    strTarget += '<w2:column width="80" inputType="text" id="ctext" dataList="ctext"></w2:column>';
    // 1 link
    strTarget += '<w2:column width="80" inputType="link" id="clink" dataList="clink"></w2:column>';
    // 2 checkbox
    strTarget += '<w2:column width="70" inputType="checkbox" id="ccheck" dataList="ccheck" trueValue="Y" falseValue="N"></w2:column>';
    // 3 button
    strTarget += '<w2:column width="70" inputType="button" id="cbtn" dataList="cbtn"></w2:column>';
    // 4 image
    strTarget += '<w2:column width="60" inputType="image" id="cimg" dataList="cimg"></w2:column>';
    // 5 radio
    strTarget += '<w2:column width="60" inputType="radio" id="cradio" dataList="cradio" trueValue="Y" falseValue="N" groupName="grp_rdo"></w2:column>';
    // 6 select
    strTarget += '<w2:column width="100" inputType="select" id="cselect" dataList="cselect">' + itemset + '</w2:column>';
    // 7 calendar
    strTarget += '<w2:column width="110" inputType="calendar" id="ccal" dataList="ccal"></w2:column>';
    // 8 expression (spinner 값 x 1000 의 계산 결과를 표시 -> 산식 컬럼임이 드러남)
    strTarget += '<w2:column width="90" inputType="expression" id="col_expr" displayFormat="#,###" expression="Number(display(\'cspin\'))*1000"></w2:column>';
    // 9 textarea
    strTarget += '<w2:column width="100" inputType="textarea" id="ctextarea" dataList="ctextarea"></w2:column>';
    // 10 drilldown
    strTarget += '<w2:column width="90" inputType="drilldown" id="cdrill" dataList="cdrill"></w2:column>';
    // 11 textImage
    strTarget += '<w2:column width="90" inputType="textImage" id="ctextimg" dataList="ctextimg" viewType="icon" imageSrc="' + imgSrc + '"></w2:column>';
    // 12 checkcombobox
    strTarget += '<w2:column width="110" inputType="checkcombobox" id="ccombo" dataList="ccombo">' + itemset + '</w2:column>';
    // 13 autoComplete
    strTarget += '<w2:column width="110" inputType="autoComplete" id="cauto" dataList="cauto">' + itemset + '</w2:column>';
    // 14 secret (값이 마스킹되어 표시 -> secret 임이 드러남)
    strTarget += '<w2:column width="70" inputType="secret" id="csecret" dataList="csecret"></w2:column>';
    // 15 custom (setColumnVisible(15,false) 로 숨김 -> 숨김 Column 도 인덱스 포함/타입 반환 검증)
    strTarget += '<w2:column width="80" inputType="custom" id="ccustom" dataList="ccustom"></w2:column>';
    // 16 spinner
    strTarget += '<w2:column width="*" inputType="spinner" id="cspin" dataList="cspin"></w2:column>';
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 인덱스 15(custom) 숨김 -> 숨김 Column 도 인덱스에 포함되며 inputType 을 반환하는지 검증용
    target1.setColumnVisible(15, false);
}



// [실행] getColumnType 전체 조회 : 버튼 1개로 모든 Column 의 inputType 을 한 번에 출력한다.
//  - 숨김 Column(인덱스 14, secret) 도 인덱스에 포함되어 inputType 을 반환
//  - 마지막에 존재하지 않는 인덱스(99) 호출로 undefined 반환도 확인
scwin.btn_getColumnType_onclick = function () {
    let cnt = target1.getColumnCount();
    let lines = [];
    for (let i = 0; i < cnt; i++) {
        let colID = target1.getColumnID(i);
        let colIDLabel = (typeof colID === 'undefined' || colID === null) ? "-" : colID;
        let visible = target1.getColumnVisible(i);
        let hideMark = (visible === false) ? " (숨김)" : "";
        lines.push("[" + i + "] " + colIDLabel + hideMark + " -> getColumnType : " + target1.getColumnType(i));
    }
    // 존재하지 않는 Column 조회 -> undefined
    let invalid = target1.getColumnType(99);
    lines.push("[99] (존재하지 않는 Column) -> getColumnType : " + (typeof invalid === 'undefined' ? "undefined" : invalid));

    wf_body_bottom.getObj("scwin").setReturnValue(lines.join("\n"));
}
